changeSet.sql:
UPDATE clients SET client_status = 'VERIFICATION_AML_REQUIRED' WHERE client_status IN ('SUSPICIOUS', 'DUE_DILIGENCE_REQUIRED', 'RE_EVALUATION_REQUIRED');
UPDATE clients SET client_status = 'VALIDATED' WHERE client_status = 'INDULGENCE_VALIDATED';
UPDATE screening_matches SET status = 'PENDING' WHERE status = 'RE_EVALUATION_REQUIRED';
